 * @param {string} layer.database - The name of the database.
 * @param {string} layer.name - The name of the layer.
 */
function initCollectionsTable(layer) {
  // Initialize DataTable for CollectionsTable
  collectionsTable = $('#CollectionsTable').DataTable({
    // AJAX configuration for fetching data from the server
    ajax: {
      url: global_stratos_url + '/api/databases/' + layer.database + '/layers/' + layer.name + '/collections',
      dataSrc: function (response) {
        // Set total number of records and store table data
        _this.SetTotal(response.data.length);
        tableData = response.data;
        return response.data; // Return the data to be displayed in the table
      },
      error: function (response) {
        // Display an error message if the AJAX request fails
        cw_Stratos_Nav.ShowErrorBox(response.responseJSON.message);
      }
    },

    // Set the row ID to the 'collection' property
    rowId: 'collection',

    // Define table columns with their respective data, titles, and custom renderers
    columns: [
      {
        data: "collection",
        title: "Collection",
        className: "dt-center"
      },
      {
        data: "title",
        title: "Title"
      },
      {
