	for (const auto& Index:NetworkIndicesToRemove)
	{
		Networks.RemoveAt(Index);
	}
	UE_LOG(LogTemp, Warning, TEXT("%i dirty  %i total  %i networks %i connections"), PortsDirty.Num(), Ports.Num(), Networks.Num(), Adjacencies.Num());

