import com.google.protobuf.InvalidProtocolBufferException;
import com.google.protobuf.Message;

public class ProtoDeserializer {

    public static <T extends Message> T deserialize(byte[] bytes, Class<T> clazz) {
        try {
            T message = clazz.getDeclaredConstructor().newInstance();
            message.parseFrom(bytes);
            return message;
        } catch (InvalidProtocolBufferException | InstantiationException | IllegalAccessException |
                 NoSuchMethodException | InvocationTargetException e) {
            throw new RuntimeException("Failed to deserialize protobuf message", e);
        }
    }

    public static void main(String[] args) {
        byte[] bytes = // your protobuf byte array here

        // Try to deserialize into Message1
        try {
            Message1 message1 = deserialize(bytes, Message1.class);
            // Handle Message1
        } catch (RuntimeException e) {
            // If deserialization into Message1 fails, try Message2
