                Message2 message2 = deserialize(bytes, Message2.class);
                // Handle Message2
            } catch (RuntimeException ex) {
                // If deserialization into Message2 also fails, handle the error
                // This could mean that the byte array is not a valid protobuf message for either Message1 or Message2
            }
        }
    }
}
```

