```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 5; // replace with your desired size

    // Calculate the total number of elements
    size_t num_elements = n * n;

    // Allocate memory for the two-dimensional array
    int *two_d_array = (int *)calloc(num_elements, sizeof(int));

    // Check if memory allocation was successful
    if (two_d_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Cast the pointer to a two-dimensional array and access elements
    int (*arr)[n] = (int (*)[n])two_d_array;

    // Access elements using arr[i][j] syntax
    for (size_t i = 0; i < n; i++) {
        for (size_t j = 0; j < n; j++) {
            arr[i][j] = i * n + j;
        }
    }

    // Print the allocated memory
    for (size_t i = 0; i < n; i++) {
        for (size_t j = 0; j < n; j++) {
            printf("%d ", arr[i][j]);
        }
