To create an automated unit testing script for a CRUD operation in NestJS with the given fields (email, password, confirm password, and submit button), we'll use Jest as the testing framework. Here's a step-by-step guide to creating the test script:

1. Install required dependencies:

```bash
npm install --save-dev @nestjs/testing @types/jest jest supertest
```

2. Create a new file named `user.entity.spec.ts` in the `src/user` directory for testing the User entity:

```typescript
// src/user/user.entity.spec.ts

import { User } from './user.entity';

describe('UserEntity', () => {
  it('should create a new user with valid data', () => {
    const user = new User();
    user.email = 'test@example.com';
    user.password = 'password';
    user.confirmPassword = 'password';

    expect(user.email).toBe('test@example.com');
    expect(user.password).toBe('password');
    expect(user.confirmPassword).toBe('password');
  });
});
```

3. Create a new file named `user.service.spec.ts` in the `src/user` directory for testing the UserService:

```typescript
// src/user/user.service.spec.ts

import { Test, TestingModule } from '@nestjs/testing';
import { UserService } from './user.service';
import { User } from './user.entity';

describe('UserService', () => {
 let service: UserService;

 beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [UserService],
    }).compile();

    service = module.get<UserService>(UserService);
  });

 describe('create', () => {
    it('should create a new user', async () => {
      const userData = {
        email: 'test@example.com',
        password: 'password',
        confirmPassword: 'password',
      };

      const createdUser = await service.create(userData);

      expect(createdUser.email).toBe('test@example.com');
      expect(createdUser.password).toBe('password');
      expect(createdUser.confirmPassword).toBeUndefined();
    });
  });

 describe('findOne', () => {
    it('should find a user by email', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      const foundUser = await service.findOne(user.email);

      expect(foundUser.email).toBe('test@example.com');
      expect(foundUser.password).toBe('password');
    });
  });

 describe('update', () => {
    it('should update a user', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      const updatedUserData = {
        email: 'updated@example.com',
        password: 'updatedPassword',
      };

      const updatedUser = await service.update(user.email, updatedUserData);

      expect(updatedUser.email).toBe('updated@example.com');
      expect(updatedUser.password).toBe('updatedPassword');
    });
  });

 describe('delete', () => {
    it('should delete a user', async () => {
      const user = new User();
      user.email = 'test@example.com';
      user.password = 'password';

      await service.create(user);
      const deletedUser = await service.delete(user.email);

      expect(deletedUser).toBeTruthy();
    });
  });
});
```

4. Create a new file named `user.controller.spec.ts` in the `src/user` directory for testing the UserController:

```typescript
// src/user/user.controller.spec.ts

import { Test, TestingModule } from '@nestjs/testing';
import { UserController } from './user.controller';
import { UserService } from './user.service';
import { User } from './user.entity';
import * as request from 'supertest';

describe('UserController', () => {
 let controller: UserController;
 let service: UserService;

 beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [UserController],
      providers: [
        {
          provide: UserService,
          useValue: {
            create: jest.fn(),
            findOne: jest.fn(),
            update: jest.fn(),
            delete: jest.fn(),
          },
        },
      ],
    }).compile();

    controller = module.get<UserController>(UserController);
    service = module.get<UserService>(UserService);
  });

 describe('create', () => {
    it('should create a new user', async () => {
      const userData = {
        email: 'test@example.com',
        password: 'password',
        confirmPassword: 'password',
      };

      const createdUser = new User();
      createdUser.email = 'test@example.com';
      createdUser.password = 'password';

      jest.spyOn(service, 'create').mockResolvedValue(createdUser);

      await request(controller.app)
        .post('/user')
        .send(userData)
        .expect(201)
        .expect(res => {
          expect(res.body.email).toBe('test@example.com');
          expect(res.body.password).toBe('password');
        });
    });
  });

  // Add similar tests for other CRUD operations
});
```

These test scripts cover the basic CRUD operations for the User entity, service, and controller. You can extend these tests to cover more complex scenarios and edge cases.
